<?php
require __DIR__ . '/_init.php'; $current = require_user();
$id = field($_GET, 'id', 36); $error = ''; $result = null; $page = ['items' => [], 'total' => 0]; $offset = page_offset();
try { $id ? $result = engine('GET', '/v1/analyses/' . uuid($id)) : $page = engine('GET', '/v1/analyses', ['limit' => 25, 'offset' => $offset]); }
catch (WebError $exception) { $error = $exception->getMessage(); }
panel_header($id ? 'Diagnóstico con evidencias' : 'Historial de análisis', 'analisis', $current);
if ($error) { notice($error); }
if ($result) {
    $diagnosis = $result['diagnosis'];
    $uncertainty = ['low' => 'Baja', 'medium' => 'Media', 'high' => 'Alta'][$diagnosis['uncertainty']] ?? 'No indicada';
    ?><a class="back-link" href="<?= e(url('analisis.php')) ?>">← Ver historial</a><div class="analysis-meta"><span>✧ <?= e($result['model']) ?></span><span><?= e(date_label($result['created_at'])) ?></span><span><?= count($result['log_ids']) ?> eventos</span><span>Prompt <?= e($result['prompt_version']) ?></span></div><section class="summary-card"><span class="eyebrow">RESUMEN DEL DIAGNÓSTICO</span><p><?= e($diagnosis['summary']) ?></p><footer><span class="tag purple">Incertidumbre <?= e(strtolower($uncertainty)) ?></span><span>Las causas son hipótesis que requieren comprobación.</span></footer></section><div class="diagnosis-grid">
    <?php foreach (['findings' => 'Hallazgos', 'possible_causes' => 'Causas posibles'] as $key => $title) { ?><section class="card diagnosis-card"><h2><?= e($title) ?></h2><?php if (!$diagnosis[$key]) { echo '<p class="muted">Sin conclusiones adicionales.</p>'; } foreach ($diagnosis[$key] as $item) { ?><div class="finding"><?php if ($key === 'possible_causes') { ?><span class="eyebrow">HIPÓTESIS</span><?php } ?><p><?= e($item['description']) ?></p><div class="citations"><?php foreach ($item['log_ids'] as $logId) { ?><a href="<?= e(url('evento.php?id=' . rawurlencode($logId))) ?>" title="<?= e($logId) ?>">↗ <?= e(substr($logId, 0, 8)) ?></a><?php } ?></div></div><?php } ?></section><?php } ?>
    <section class="card diagnosis-card evidence-card"><h2>Evidencias</h2><?php foreach ($diagnosis['evidence'] as $item) { ?><div class="evidence-row"><a class="evidence-link" href="<?= e(url('evento.php?id=' . rawurlencode($item['log_id']))) ?>" title="<?= e($item['log_id']) ?>">↗ <?= e(substr($item['log_id'], 0, 8)) ?></a><p><?= e($item['explanation']) ?></p></div><?php } ?></section>
    <?php foreach (['next_checks' => 'Próximas comprobaciones', 'missing_information' => 'Información que falta'] as $key => $title) { ?><section class="card diagnosis-card"><h2><?= e($title) ?></h2><ul><?php foreach ($diagnosis[$key] as $item) { ?><li><?= e($item) ?></li><?php } ?></ul><?php if (!$diagnosis[$key]) { ?><p class="muted">El modelo no ha indicado información adicional.</p><?php } ?></section><?php } ?></div><p class="analysis-id">Análisis <?= e($result['id']) ?></p>
<?php } elseif (!$id) { ?><section class="card"><div class="card-heading"><div><h2>Diagnósticos guardados</h2><p>El contexto y las evidencias de cada análisis.</p></div><span class="tag"><?= (int)$page['total'] ?> EN TOTAL</span></div><?php if (!$page['items']) { empty_state('Un historial por construir', 'Selecciona eventos y solicita tu primer diagnóstico.'); } foreach ($page['items'] as $item) { ?><a class="history-item" href="<?= e(url('analisis.php?id=' . rawurlencode($item['id']))) ?>"><span class="feature-icon">✧</span><div><h3><?= e($item['diagnosis']['summary']) ?></h3><p><?= e(date_label($item['created_at'])) ?> · <?= count($item['log_ids']) ?> eventos · <?= e($item['model']) ?></p></div><span>↗</span></a><?php } pager((int)$page['total'], $offset, 'analisis.php'); ?></section><?php } panel_footer(); ?>
